#!/usr/bin/env dotnet
#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count how many exist in a full 400-year cycle.

// Find earliest Friday the 13th
DateOnly earliest = default;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
            {
                earliest = date;
                Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");
            }
        }
    }
}

// Count Friday the 13ths in one full 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var date = new DateOnly(year, month, 13);
        if (date.DayOfWeek == DayOfWeek.Friday)
            byMonth[month - 1]++;
    }
}

Console.WriteLine("\nDistribution by month (over 400 years):");
for (int m = 0; m < 12; m++)
{
    var name = new DateOnly(2000, m + 1, 1).ToString("MMMM");
    Console.WriteLine($"  {name,-12} {byMonth[m]}");
}

